-- Demo content only. Reapply using the reset script on this isolated project.
update private.demo_settings set enabled=true,order_prefix='PK' where id;
select setval(pg_get_serial_sequence('public.stores','id'),greatest((select max(id) from public.stores),1));
select setval(pg_get_serial_sequence('public.categories','id'),greatest((select max(id) from public.categories),1));
select setval(pg_get_serial_sequence('public.products','id'),greatest((select max(id) from public.products),1));
select setval(pg_get_serial_sequence('public.campaigns','id'),greatest((select max(id) from public.campaigns),1));
update public.reward_settings set points_enabled=true,stamp_enabled=false;
update public.voucher_templates set title='Demo Treat: Buy 2, Free 1' where id=1 and voucher_type='buy_x_free_one';
update public.voucher_codes set code='DEMOWELCOME' where id=1;
update public.voucher_codes set code='DEMOBUY2' where id=2;
